"""The Conviction port against goldens generated by the OLD code (``python -m projectzero.ops.parity_conviction
goldens``): ``taste.score`` (every ladder value, penalties, verified-zeroing, clamps, bands, bad values), ``imq.evaluate``
(gates A-E, the conflict gate, the 90-day window at a fixed clock), ``imq.persist``, ``days_since`` and ``/api/meta``."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import pytest

from projectzero.ops.parity_conviction import diff, new_rules, rules_input

GOLDEN: dict[str, Any] = json.loads(
    (Path(__file__).resolve().parents[1] / "fixtures" / "golden_v1" / "oracle_conviction.json").read_text(
        encoding="utf-8"
    )
)
NEW = new_rules(GOLDEN["input"])


def test_provenance_is_the_clean_old_revision() -> None:
    assert GOLDEN["provenance"]["old_revision"] == "6c739b9cb6ca2517b845e381d39a36c50eccc59e"
    assert GOLDEN["provenance"]["old_dirty"] is False
    assert GOLDEN["provenance"]["clock"] == "2026-11-11T12:00:00"


def test_the_golden_input_is_the_current_corpus() -> None:
    """The corpus in code and the one the oracle saw are the same (no silent drift of the test set)."""
    assert json.loads(json.dumps(rules_input())) == GOLDEN["input"]


@pytest.mark.parametrize("section", ["score", "evaluate", "persist", "days", "api_meta"])
def test_section_matches_the_old_code(section: str) -> None:
    assert diff(GOLDEN["expected"][section], NEW[section]) == []


def test_the_corpus_covers_every_state_and_the_90_day_line() -> None:
    states = {r["ok"]["state"] for r in GOLDEN["expected"]["evaluate"] if "ok" in r}
    assert states == {"NOT YET IMQ", "IMQ — QUALIFIED NOW", "CONFLICT GATED", "IMQ — STALE"}
    by_date = {
        c["entry"]["imq_trigger"]["date"]: r["ok"]["timing"]["established"]
        for c, r in zip(GOLDEN["input"]["evaluate"], GOLDEN["expected"]["evaluate"], strict=True)
        if "ok" in r and isinstance(c["entry"].get("imq_trigger"), dict) and c["entry"]["imq_trigger"].get("date")
    }
    assert by_date["2026-08-13"] is True and by_date["2026-08-12"] is False  # exactly 90 days in, 91 out
    persisted = [p for p in GOLDEN["expected"]["persist"] if p["changed"]]
    assert {p["state"] for p in persisted} == {"IMQ — QUALIFIED NOW", "IMQ — STALE", "CONFLICT GATED"}


def test_some_stored_values_raise_in_the_frozen_score() -> None:
    """The pipeline reads those on a neutral copy (``data_warning``); the score itself stays frozen."""
    assert sum(1 for r in GOLDEN["expected"]["score"] if "raises" in r) == 4
